{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "The highest-transfer analogue showed Kpuu = 1 in rat in vivo studies and was explicitly labelled high permeability, directly demonstrating that a large, basic, heteroaromatic molecule can achieve excellent unbound brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Human imaging with [11C]CURB, which contains the same piperidinoethoxyphenyl motif as the query, showed rapid and high brain uptake, directly transferring the key CNS-penetrant substructure to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "UNC2025 achieved a brain/plasma AUC ratio of 2.0 in mice and was labelled high permeability, showing that a high-molecular-weight, basic, heteroaromatic molecule can achieve meaningful CNS exposure after systemic dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Fedratinib showed high unbound brain-to-unbound plasma distribution in rats, exceeding PSA-based expectations, indicating that basic, high-molecular-weight molecules can still achieve effective brain uptake.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Dixyrazine penetrated rapidly into human CSF with a CSF/P ratio of 0.3 and was classified as permeable, supporting meaningful CNS access for a high-molecular-weight piperazine-containing molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Baboon PET imaging showed BBB penetration of a large piperazine-containing radioligand with brain uptake proportional to 5-HT1A receptor density, confirming that this chemotype can access the CNS.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Despite the physicochemical prior predicting low passive permeability and efflux liability, multiple high-transfer direct in vivo measurements in rats, mice, baboons, pigs, and humans demonstrate that close analogues—including one sharing the piperidinoethoxyphenyl motif—achieve meaningful CNS exposure (Kpuu=1, brain/plasma AUC=2, CSF/P=0.3, PET uptake). The prediction is pass.",
  "evidence_gaps": [
    "No direct Kpuu, CSF, or PET measurement exists for the exact query molecule.",
    "The query is dicationic at physiological pH, and no analogue with exactly two fully ionized basic centers was directly measured.",
    "Efflux transporter contribution for the query specifically is not quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

